    neighs = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            neighs.append(grid[nr][nc])
    # Remove duplicates for majority voting
    from collections import Counter
    return Counter(neighs)

